/// <summary>
/// Called once from Program.cs. Every line below is the DEFAULT, not the answer: single- or
/// multi-stream, registered Inline. Marten also offers EventProjection (one event, many documents),
/// FlatTableProjection (a SQL table, not a document), composite/chained projections and raw
/// IProjection — see reference/llms/marten/events/projections/ and
/// reference-implementations/state-view/.
///
/// Changing a line here is the supported way to choose. Regeneration KEEPS this file.
///
/// Two costs to know before moving anything off Inline:
///   - Inline updates the view in the append's own transaction, so a GWT's THEN is assertable the
///     moment the request returns. Async means tests must WAIT instead of assert.
///   - Async needs the daemon: AddAsyncDaemon(DaemonMode.Solo) on the Marten chain, or nothing runs
///     and Marten only warns.
/// </summary>
public static class ViewRegistrations
{
    public static void Register(StoreOptions opts)
    {
        // A HINT A HUMAN READS — Async, which is codegen's default for a multi-stream view and Marten's own
        // guidance. Nothing decides from this row, so a stale one costs a retry and never correctness.
        opts.Projections.Add<PoolAvailabilityProjection>(ProjectionLifecycle.Async);

        // A PROCESSOR'S WORK QUEUE — INLINE, and this is a DELIBERATE DEPARTURE from the line above.
        //
        // Marten's guidance ("register the lookup projection inline and the multi-stream projection async")
        // is about a view somebody READS. A todo View is not that: an automation's liveness depends on it,
        // and Understanding EventSourcing ch. 32 names the failure exactly — "entries get lost if the
        // processor was running before the model got updated". Async here means the wakeup can arrive
        // before the row exists, the trigger finds nothing, and the reservation is never executed and never
        // compensated. On the release list that leaks a unit of the limited resource permanently.
        //
        // Inline puts the row in the append's own transaction, so by the time anything is woken by
        // SlotReserved the row it needs is already committed. MEASURED, not assumed: flip either of these
        // to Async and AsyncTodoViewLosesWork in the concurrency tests reproduces the loss.
        //
        // The costs are the ones the book names for Inline and they are real: the write side is no longer
        // independently scalable, and an exception in either projection aborts the business transaction
        // that appended the event. Both are accepted here because the alternative is losing work silently.
        opts.Projections.Add<SlotsToIssueProjection>(IssueGrantWakeup.LifecycleOf(ProjectionLifecycle.Inline));
        opts.Projections.Add<SlotsToReleaseProjection>(ReleaseSlotWakeup.LifecycleOf(ProjectionLifecycle.Inline));
    }

    /// <summary>
    /// The read side sometimes needs the STORE and not just its options. Any projection registered Async
    /// runs in the async daemon, and WITHOUT THE DAEMON NOTHING PROCESSES IT — Marten only logs a warning
    /// at startup, so the symptom is a view that stays empty for ever with a clean build and a clean boot.
    ///
    /// Solo rather than HotCold: one node, no leader election, much faster startup.
    /// </summary>
    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        // PoolAvailability is Async, so it needs the daemon. WITHOUT THIS LINE it never updates and Marten
        // only logs a warning — a view that stays empty for ever with a clean build and a clean boot.
        //
        // The two todo Views are Inline and would not need it. The daemon is here for the hint, and a
        // wakeup mechanism may also want it (IssueGrantWakeup.ConfigureStore asks separately, which is
        // harmless: AddAsyncDaemon is idempotent in effect because Marten keeps one daemon per store).
        marten.AddAsyncDaemon(DaemonMode.Solo);
    }
}
